-- Observability and admin: system tables, query logs, parts, merges
SELECT query_id, query, query_duration_ms, read_rows, memory_usage FROM system.query_log WHERE type = 'QueryFinish' AND event_time > now() - INTERVAL 1 HOUR ORDER BY query_duration_ms DESC LIMIT 20;
SELECT normalizedQueryHash(query) AS h, count() AS c, avg(query_duration_ms) AS avg_ms, quantile(0.95)(query_duration_ms) AS p95 FROM system.query_log WHERE event_date = today() AND type = 'QueryFinish' GROUP BY h ORDER BY c DESC LIMIT 20;
SELECT database, table, sum(rows) AS total_rows, formatReadableSize(sum(bytes_on_disk)) AS size, count() AS parts FROM system.parts WHERE active GROUP BY database, table ORDER BY sum(bytes_on_disk) DESC;
SELECT table, partition, name, rows, modification_time FROM system.parts WHERE active AND database = 'default' AND table = 'events' ORDER BY modification_time DESC LIMIT 10;
SELECT * FROM system.merges;
SELECT * FROM system.mutations WHERE NOT is_done;
SELECT * FROM system.replicas WHERE is_readonly OR absolute_delay > 60;
SELECT * FROM system.processes ORDER BY elapsed DESC;
SELECT metric, value FROM system.metrics WHERE metric LIKE 'Memory%';
SELECT event, value FROM system.events WHERE event IN ('Query', 'SelectQuery', 'InsertQuery');
SELECT name, value, changed FROM system.settings WHERE changed;
SELECT database, name, engine, total_rows, total_bytes FROM system.tables WHERE database NOT IN ('system', 'INFORMATION_SCHEMA', 'information_schema');
SELECT database, table, name, type, compression_codec FROM system.columns WHERE database = 'default';
SELECT hostName(), uptime(), version(), currentUser(), currentDatabase();
SELECT toStartOfMinute(event_time) AS m, count() FROM system.query_log GROUP BY m ORDER BY m;
SELECT arrayJoin(stack_trace) FROM system.stack_trace LIMIT 5;
SELECT exception_code, any(exception) AS ex, count() FROM system.query_log WHERE exception_code != 0 GROUP BY exception_code ORDER BY count() DESC;
SELECT user, count() FROM system.query_log WHERE query_kind = 'Select' GROUP BY user;
SELECT query, ProfileEvents['SelectedRows'] AS rows_read, ProfileEvents['RealTimeMicroseconds'] AS rt FROM system.query_log WHERE type = 'QueryFinish' LIMIT 5;
SELECT tables, Settings['max_threads'] FROM system.query_log LIMIT 1;
SELECT disk_name, formatReadableSize(free_space), formatReadableSize(total_space) FROM system.disks;
SELECT * FROM system.asynchronous_metrics WHERE metric LIKE '%Memory%';
SELECT * FROM system.clusters WHERE cluster = 'my_cluster';
SELECT * FROM system.zookeeper WHERE path = '/clickhouse';
SELECT * FROM system.part_log WHERE event_type = 'MergeParts' AND event_date = today();
SHOW TABLES;
SHOW DATABASES;
SHOW TABLES FROM system LIKE 'query%';
SHOW CREATE TABLE events;
DESCRIBE TABLE events;
DESC events;
EXISTS TABLE events;
USE analytics;
SET max_threads = 8;
SYSTEM FLUSH LOGS;
SYSTEM DROP DNS CACHE;
SYSTEM STOP MERGES events;
SYSTEM START MERGES events;
SYSTEM SYNC REPLICA events;
KILL QUERY WHERE query_id = 'abc' SYNC;
KILL MUTATION WHERE database = 'default' AND table = 'events';
EXPLAIN SELECT * FROM events WHERE user_id = 1;
EXPLAIN PIPELINE SELECT count() FROM events;
EXPLAIN AST SELECT 1;
EXPLAIN SYNTAX SELECT 1 + 1;
EXPLAIN indexes = 1 SELECT * FROM events WHERE user_id = 1;
